from cloudlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
b = Board('Cloud_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it shows', ul('Where things run and how they are joined: regions, networks, subnets, servers, gateways and the links between sites.', 'Not what the software does (Architecture) or how the code is cut up (C4). The same boxes can appear in both, with the same name, tint and icon.', 'Three drawings are shown: a basic one-VPC web app, the full delivery platform on two zones, and a network joining offices to the cloud.')),
 card('Frames', ul('Frames nest: <b>edge / region</b> then <b>VPC</b> then <b>zone</b> then <b>subnet</b>. A part sits in the smallest frame that holds it.', 'Kinds and tints: region blue (solid), VPC violet, zone grey, public subnet green, private subnet amber, data subnet teal, on-premises site slate (solid), DMZ red, edge violet.', 'Label: a dark pill on the top edge, in the frame colour, top left. Lines never enter the frame next to the pill.', '30 px between a frame and the next frame inside it; 40 px between a subnet edge and its parts.')),
 card('Parts', ul('Plain parts only, 196 × 68, flat icon from the Cloud services set (Load balancer, Kubernetes, SQL database, Message queue, Firewall / WAF, Virtual network, CDN, Object storage...).', 'Name by role (<i>Primary database</i>). Detail line: technology or zone (<i>PostgreSQL</i>, <i>zone a</i>).', 'The same role in two zones is drawn twice with the same name and the zone in the detail line.', 'A managed service that is not in a VPC (queue, storage) sits in the region frame, outside the VPC.')),
 card('Trust levels', ul('Top to bottom: internet and edge, public subnet, private subnet, data subnet. A line may skip no more than one level.', 'Public holds what faces the internet (load balancer, VPN gateway). Private holds the code. Data holds databases and caches.', 'A DMZ is a public subnet with a red frame: it holds only what outsiders may touch (bastion, VPN end).', 'Drawing a database in a public subnet is a mistake; a plugin should refuse it.')),
 card('Lines', ul('Same roles as every diagram: main blue thick animated, event or copy violet thin slow, everything else ink.', 'Label: a protocol or what travels (<i>HTTPS</i>, <i>IPsec VPN</i>, <i>replication</i>). Leave 90 px of line for it.', 'Place a label between frames, not on a frame edge.', 'A link between sites is drawn from device to device (firewall to gateway), never frame to frame.')),
 card('Layout', ul('Frames on a 40 px grid. Zones side by side, subnets stacked in the same order in every zone so a reader can compare them.', 'Parts of one row share a centre line; rows are 255 px apart.', 'Sites and outside parties sit outside the region. Remote users sit above the diagram, on-premises sites to the left.', 'More than about sixteen parts: split by region or by network.')),
 card('Animation', ul('One blue route: one request, from user to data. Violet: the event stream or the database copy.', 'Frames, tunnels between sites and everything else are static, except a second site tunnel, which may be violet.', 'In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('What a plugin can rely on', ul('A frame is: kind, label, parent frame. Frames nest; the plugin sizes a frame from its children plus padding.', 'A part is: id, name, detail, icon, tone, frame. A link is: from, to, kind, label.', 'Checks: part in the right trust level, no line skipping two levels, label not on a frame edge.', 'Not covered: route tables, security-group rules, CIDR planning, multi-region failover.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Cloud · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">Cloud, network and deployment diagrams show where things run. These are the conventions every one follows, and that a plugin can rely on. The three examples next to it are a basic web app, the delivery platform and a network of sites.</div></div>{grid}</div>')
print(save9(b))
